"""Model loading shared by the loop-level tests that run without cameras (the scene and spawn of experiments/cc_loop_tests.py)."""

from pathlib import Path

from src import robot_specs
from src.simulator import RobotSimulator

PROJECT_ROOT = Path(__file__).resolve().parent.parent
SCENE = "models/scenes/chemistry_lab_combined.xml"
SPAWN = [-1.0, 3.5, 0.22]


def load():
    """Loads the combined lab scene with the pedestal and no cameras; returns (model, data)."""
    sim = RobotSimulator(model_path=str(PROJECT_ROOT / SCENE), cameras=None, pedestal_lift=robot_specs.PEDESTAL_SPECS)
    return sim.model, sim.data


def steps_per_frame(model, tick_hz=150.0):
    """Physics steps per control tick at `tick_hz`."""
    return max(1, round(1.0 / model.opt.timestep / tick_hz))
